using System;using System.Data;using System.Data.SqlClient;using System.Web;namespace schoolms{public partial class student_Profile:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){string enrl=Session["Stud"] as string;if(enrl==null){Response.Redirect("Student_Login.aspx");return;}if(!IsPostBack)LoadProfile(enrl);}void LoadProfile(string enrl){try{using(SqlConnection c=Db.CreateConnection())using(SqlCommand q=new SqlCommand("SELECT EnrlNo,Name,Age,City,ClassNo FROM Stud WHERE EnrlNo=@E",c)){q.Parameters.Add("@E",SqlDbType.NVarChar,30).Value=enrl;c.Open();using(SqlDataReader r=q.ExecuteReader()){if(r.Read()){litWelcome.Text="Welcome, "+HttpUtility.HtmlEncode(r.GetString(1));litEnrl.Text=HttpUtility.HtmlEncode(r.GetString(0));litName.Text=HttpUtility.HtmlEncode(r.GetString(1));litAge.Text=r.GetInt32(2).ToString();litCity.Text=r.IsDBNull(3)?"-":HttpUtility.HtmlEncode(r.GetString(3));litClass.Text=r.IsDBNull(4)?"-":"Class "+r.GetInt32(4);}}}}catch(SqlException){Db.Alert(this,"Could not load your profile.");}}}}
